handler.function:
try {
  console.log('🤖 [support_agent] Processing user request');

  const systemMessage = { 
    role: 'system', 
    content: (model.systemPrompt || '') + (skillsContent || '') 
  };

  const messages = [systemMessage, ...state.messages];

  console.log('📤 [support_agent] Invoking model with', messages.length, 'messages');
  const result = await model.invoke(messages);

  console.log('✅ [support_agent] Model response received');
  return { messages: [result] };
}
catch (error) {
  console.error('❌ [support_agent] Error:', error);
  return { 
    messages: [{ role: 'assistant', content: `Error: ${error.message}` }]
  };
}

try {
  const lastMessage = state.messages[state.messages.length - 1];
  const resultMessage = lastMessage?.content || 'No response generated';

  interrupt(resultMessage);

  console.log('🔍 Final result:', resultMessage);

  return {
    messages: []
  };
}
catch (error) {
  console.error('❌ [showResult] Error:', error);
  return { 
    messages: [{ role: 'assistant', content: `Error: ${error.message}` }]
  };
}
